import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force HIP compilation on ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused INT4 unpack + dequant + GEMM
# x: (M,K) fp16
# weight_packed: (N,K/2) uint8 packed int4 (low nibble first)
# scales: (N, K/group_size) fp16
# out: (M,N) fp16, accumulate fp32

src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

#ifndef __HIP_PLATFORM_AMD__
#define __HIP_PLATFORM_AMD__
#endif

// Use __half from HIP

__device__ __forceinline__ int int4_from_packed(uint8_t byte, bool high) {
    return high ? ((byte >> 4) & 0x0F) : (byte & 0x0F);
}

__global__ void int4_gemm_fused_kernel(
    const half* __restrict__ x,        // (M,K)
    const uint8_t* __restrict__ wpk,   // (N,K/2)
    const half* __restrict__ scales,   // (N,Kg)
    half* __restrict__ out,            // (M,N)
    int M, int N, int K, int Kg, int group_size)
{
    // 2D tile mapping
    int m = (int)(blockIdx.y * blockDim.y + threadIdx.y);
    int n = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    if (m >= M || n >= N) return;

    float acc = 0.0f;

    // Iterate K; unpack weights on the fly
    // weights packed along K/2
    const half* xrow = x + (size_t)m * K;
    const uint8_t* wrow = wpk + (size_t)n * (K/2);
    const half* srow = scales + (size_t)n * Kg;

    // Unroll by 2 to reuse packed byte
    for (int k2 = 0; k2 < K/2; ++k2) {
        uint8_t byte = wrow[k2];

        int k0 = k2 * 2;
        int g0 = k0 / group_size;
        float s0 = __half2float(srow[g0]);
        int wq0 = int4_from_packed(byte, false);
        float w0 = s0 * ((float)wq0 - 8.0f);
        float x0 = __half2float(xrow[k0]);
        acc = fmaf(x0, w0, acc);

        int k1 = k0 + 1;
        int g1 = k1 / group_size;
        float s1 = __half2float(srow[g1]);
        int wq1 = int4_from_packed(byte, true);
        float w1 = s1 * ((float)wq1 - 8.0f);
        float x1 = __half2float(xrow[k1]);
        acc = fmaf(x1, w1, acc);
    }

    out[(size_t)m * N + n] = __float2half_rn(acc);
}

torch::Tensor int4_gemm_fused_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int64_t group_size) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(weight_packed.is_cuda(), "weight_packed must be CUDA/HIP tensor");
    TORCH_CHECK(scales.is_cuda(), "scales must be CUDA/HIP tensor");

    TORCH_CHECK(x.scalar_type() == at::kHalf, "x must be fp16");
    TORCH_CHECK(weight_packed.scalar_type() == at::kByte, "weight_packed must be uint8");
    TORCH_CHECK(scales.scalar_type() == at::kHalf, "scales must be fp16");

    TORCH_CHECK(x.dim() == 2, "x must be 2D (M,K)");
    TORCH_CHECK(weight_packed.dim() == 2, "weight_packed must be 2D (N,K/2)");
    TORCH_CHECK(scales.dim() == 2, "scales must be 2D (N,Kg)");

    int64_t M = x.size(0);
    int64_t K = x.size(1);
    int64_t N = weight_packed.size(0);
    TORCH_CHECK(weight_packed.size(1) * 2 == K, "weight_packed second dim must be K/2");
    TORCH_CHECK(K % group_size == 0, "K must be divisible by group_size");
    TORCH_CHECK(K % 2 == 0, "K must be even");

    int64_t Kg = K / group_size;
    TORCH_CHECK(scales.size(0) == N && scales.size(1) == Kg, "scales must be (N, K/group_size)");

    auto out = torch::empty({M, N}, torch::TensorOptions().dtype(at::kHalf).device(x.device()));

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    hipLaunchKernelGGL(int4_gemm_fused_kernel,
        grid, block, 0, 0,
        (const half*)x.data_ptr<at::Half>(),
        (const uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (const half*)scales.data_ptr<at::Half>(),
        (half*)out.data_ptr<at::Half>(),
        (int)M, (int)N, (int)K, (int)Kg, (int)group_size);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("int4_gemm_fused_hip", &int4_gemm_fused_hip, "Fused INT4 GEMM (HIP)");
}
"""

int4ext = load_inline(
    name="int4_gemm_fused_ext",
    cpp_sources="",
    cuda_sources=src,
    functions=None,
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        assert K % group_size == 0
        assert K % 2 == 0

        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8, device="cuda")
        )
        self.register_buffer(
            "scales",
            (torch.randn(N, self.num_groups, dtype=torch.float16, device="cuda").abs() * 0.1)
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape
        x2d = x.view(-1, self.K).contiguous()
        out2d = int4ext.int4_gemm_fused_hip(x2d, self.weight_packed, self.scales, self.group_size)
        return out2d.view(batch_size, seq_len, self.N)


# KernelBench hooks
batch_size = 4
seq_len = 2048
K = 4096
N = 11008
group_size = 128


def get_inputs():
    return [torch.randn(batch_size, seq_len, K, dtype=torch.float16, device="cuda")]


def get_init_inputs():
    return [K, N, group_size]

import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Build HIP extension (FP32)
os.environ.setdefault("CXX", "hipcc")

hip_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

// -------------------- SiLU(a) * b --------------------
__device__ __forceinline__ float silu_f32(float x) {
    // x / (1 + exp(-x))
    return x / (1.0f + __expf(-x));
}

__global__ void silu_mul_kernel(const float* __restrict__ a,
                               const float* __restrict__ b,
                               float* __restrict__ out,
                               int64_t n) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (int64_t i = idx; i < n; i += stride) {
        float av = a[i];
        out[i] = silu_f32(av) * b[i];
    }
}

torch::Tensor silu_mul_hip(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "inputs must be CUDA/HIP tensors");
    TORCH_CHECK(a.scalar_type() == torch::kFloat32 && b.scalar_type() == torch::kFloat32, "FP32 only");
    TORCH_CHECK(a.is_contiguous() && b.is_contiguous(), "contiguous only");
    TORCH_CHECK(a.numel() == b.numel(), "size mismatch");

    auto out = torch::empty_like(a);
    int64_t n = a.numel();

    const int threads = 256;
    // cap blocks to avoid oversubscription
    int blocks = (int)((n + threads - 1) / threads);
    blocks = blocks > 4096 ? 4096 : blocks;

    hipLaunchKernelGGL(silu_mul_kernel, dim3(blocks), dim3(threads), 0, 0,
                       (const float*)a.data_ptr<float>(),
                       (const float*)b.data_ptr<float>(),
                       (float*)out.data_ptr<float>(), n);
    return out;
}

// -------------------- Weighted sum over top-k --------------------
// expert_out: [T, K, H] contiguous
// weights:    [T, K] contiguous
// out:        [T, H]
__global__ void moe_weighted_sum_kernel(const float* __restrict__ expert_out,
                                       const float* __restrict__ weights,
                                       float* __restrict__ out,
                                       int T, int K, int H) {
    int idx = (int)blockIdx.x * blockDim.x + threadIdx.x;
    int stride = (int)blockDim.x * gridDim.x;
    int total = T * H;

    for (int linear = idx; linear < total; linear += stride) {
        int t = linear / H;
        int h = linear - t * H;
        float acc = 0.0f;
        int base_e = (t * K) * H + h;
        int base_w = t * K;
        #pragma unroll
        for (int k = 0; k < 8; ++k) {
            // handle K<=8 typical; if K<8 this will branch
            if (k < K) {
                acc += expert_out[base_e + k * H] * weights[base_w + k];
            }
        }
        out[linear] = acc;
    }
}

torch::Tensor moe_weighted_sum_hip(torch::Tensor expert_out, torch::Tensor weights) {
    TORCH_CHECK(expert_out.is_cuda() && weights.is_cuda(), "inputs must be CUDA/HIP tensors");
    TORCH_CHECK(expert_out.scalar_type() == torch::kFloat32 && weights.scalar_type() == torch::kFloat32, "FP32 only");
    TORCH_CHECK(expert_out.is_contiguous() && weights.is_contiguous(), "contiguous only");
    TORCH_CHECK(expert_out.dim() == 3, "expert_out must be [T,K,H]");
    TORCH_CHECK(weights.dim() == 2, "weights must be [T,K]");

    int T = (int)expert_out.size(0);
    int K = (int)expert_out.size(1);
    int H = (int)expert_out.size(2);
    TORCH_CHECK(weights.size(0) == T && weights.size(1) == K, "shape mismatch");

    auto out = torch::empty({T, H}, expert_out.options());

    int total = T * H;
    const int threads = 256;
    int blocks = (total + threads - 1) / threads;
    blocks = blocks > 4096 ? 4096 : blocks;

    hipLaunchKernelGGL(moe_weighted_sum_kernel, dim3(blocks), dim3(threads), 0, 0,
                       (const float*)expert_out.data_ptr<float>(),
                       (const float*)weights.data_ptr<float>(),
                       (float*)out.data_ptr<float>(), T, K, H);
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("silu_mul_hip", &silu_mul_hip, "silu(a)*b (HIP, FP32)");
    m.def("moe_weighted_sum_hip", &moe_weighted_sum_hip, "MoE weighted sum over top-k (HIP, FP32)");
}
"""

ext = load_inline(
    name="deepseek_moe_hip_ext",
    cpp_sources="",
    cuda_sources=hip_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class MoEGate(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()
        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        group_scores = (
            scores_for_choice.view(bsz * seq_len, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(bsz * seq_len, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(bsz * seq_len, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)
        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor
        return topk_idx, topk_weight


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        n_shared_experts: int = 0,
        routed_scaling_factor: float = 1.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.n_routed_experts = n_routed_experts
        self.num_experts_per_tok = num_experts_per_tok
        self.n_shared_experts = n_shared_experts

        self.gate_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(n_routed_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gate = MoEGate(
            hidden_size=hidden_size,
            n_routed_experts=n_routed_experts,
            num_experts_per_tok=num_experts_per_tok,
            n_group=n_group,
            topk_group=topk_group,
            routed_scaling_factor=routed_scaling_factor,
        )

        if n_shared_experts > 0:
            shared_intermediate = intermediate_size * n_shared_experts
            self.shared_gate_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_up_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_down_proj = nn.Linear(shared_intermediate, hidden_size, bias=False)
        else:
            self.shared_gate_proj = None

        self._ext = ext

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        assert not self.training, "DeepSeek MoE grouped selection is inference-only"

        identity = hidden_states
        orig_shape = hidden_states.shape
        bsz, seq_len, _ = orig_shape

        topk_idx, topk_weight = self.gate(hidden_states)

        hidden_states = hidden_states.view(-1, self.hidden_size)
        num_tokens = hidden_states.shape[0]

        flat_topk_idx = topk_idx.reshape(-1)

        expanded_tokens = hidden_states.unsqueeze(1).expand(-1, self.num_experts_per_tok, -1)
        expanded_tokens = expanded_tokens.reshape(-1, self.hidden_size)

        selected_gate = self.gate_proj[flat_topk_idx]
        selected_up = self.up_proj[flat_topk_idx]
        selected_down = self.down_proj[flat_topk_idx]

        x = expanded_tokens.unsqueeze(-1)
        gate_out = torch.bmm(selected_gate, x).squeeze(-1)
        up_out = torch.bmm(selected_up, x).squeeze(-1)

        # Fused SiLU + multiply (FP32 HIP)
        gate_out_c = gate_out.contiguous()
        up_out_c = up_out.contiguous()
        intermediate = self._ext.silu_mul_hip(gate_out_c, up_out_c)

        expert_out = torch.bmm(selected_down, intermediate.unsqueeze(-1)).squeeze(-1)
        expert_out = expert_out.view(num_tokens, self.num_experts_per_tok, self.hidden_size).contiguous()

        # Fused weighted sum over top-k (FP32 HIP)
        y = self._ext.moe_weighted_sum_hip(expert_out, topk_weight.contiguous())
        y = y.view(*orig_shape)

        if self.shared_gate_proj is not None:
            shared_out = self.shared_down_proj(
                F.silu(self.shared_gate_proj(identity)) * self.shared_up_proj(identity)
            )
            y = y + shared_out

        return y

import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Compile with hipcc
os.environ.setdefault("CXX", "hipcc")

# --- Fused causal mask + softmax (FP32) ---
causal_softmax_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_xor(val, offset));
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_xor(val, offset);
    return val;
}

__global__ void causal_softmax_f32_kernel(const float* __restrict__ scores,
                                         float* __restrict__ out,
                                         int S) {
    // One block per row: (B*H*S) rows of length S
    int row = (int)blockIdx.x;
    int tid = (int)threadIdx.x;

    // row corresponds to query position i = row % S
    int i = row % S;
    const float* row_in = scores + ((size_t)row) * (size_t)S;
    float* row_out = out + ((size_t)row) * (size_t)S;

    // 1) max over j<=i
    float local_max = -INFINITY;
    for (int j = tid; j <= i; j += (int)blockDim.x) {
        float v = row_in[j];
        local_max = fmaxf(local_max, v);
    }

    // reduce within block (warp then block)
    local_max = warp_reduce_max(local_max);

    __shared__ float smem_max[32];
    int warp = tid >> 5;
    int lane = tid & 31;
    if (lane == 0) smem_max[warp] = local_max;
    __syncthreads();

    float block_max = -INFINITY;
    if (warp == 0) {
        block_max = (tid < ((blockDim.x + 31) >> 5)) ? smem_max[lane] : -INFINITY;
        block_max = warp_reduce_max(block_max);
    }
    __shared__ float s_max;
    if (tid == 0) s_max = block_max;
    __syncthreads();
    float m = s_max;

    // 2) sum exp over j<=i
    float local_sum = 0.0f;
    for (int j = tid; j <= i; j += (int)blockDim.x) {
        local_sum += __expf(row_in[j] - m);
    }

    local_sum = warp_reduce_sum(local_sum);

    __shared__ float smem_sum[32];
    if (lane == 0) smem_sum[warp] = local_sum;
    __syncthreads();

    float block_sum = 0.0f;
    if (warp == 0) {
        block_sum = (tid < ((blockDim.x + 31) >> 5)) ? smem_sum[lane] : 0.0f;
        block_sum = warp_reduce_sum(block_sum);
    }
    __shared__ float s_sum;
    if (tid == 0) s_sum = block_sum;
    __syncthreads();

    float inv_denom = 1.0f / s_sum;

    // 3) write softmax probabilities, causal mask (j>i => 0)
    for (int j = tid; j < S; j += (int)blockDim.x) {
        float v = (j <= i) ? (__expf(row_in[j] - m) * inv_denom) : 0.0f;
        row_out[j] = v;
    }
}

torch::Tensor causal_softmax_f32(torch::Tensor scores) {
    TORCH_CHECK(scores.is_cuda(), "scores must be CUDA/HIP tensor");
    TORCH_CHECK(scores.scalar_type() == at::kFloat, "scores must be float32");
    TORCH_CHECK(scores.dim() == 4, "scores must be [B,H,S,S]");
    TORCH_CHECK(scores.is_contiguous(), "scores must be contiguous");

    auto B = (int)scores.size(0);
    auto H = (int)scores.size(1);
    auto S = (int)scores.size(2);
    TORCH_CHECK(scores.size(3) == S, "scores last dim must equal S");

    auto out = torch::empty_like(scores);

    int rows = B * H * S;
    dim3 grid(rows);
    dim3 block(256);

    hipLaunchKernelGGL(causal_softmax_f32_kernel, grid, block, 0, at::hip::getDefaultHIPStream(),
                       (const float*)scores.data_ptr<float>(), (float*)out.data_ptr<float>(), S);
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("causal_softmax_f32", &causal_softmax_f32, "Fused causal mask + softmax (float32)");
}
"""

causal_softmax_mod = load_inline(
    name="causal_softmax_ext",
    cpp_sources=causal_softmax_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class DeepSeekRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)


def rotate_half(x):
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class DeepSeekRotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=2048, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos(), emb.sin()


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        q_lora_rank: int,
        kv_lora_rank: int,
        qk_nope_head_dim: int,
        qk_rope_head_dim: int,
        v_head_dim: int,
        max_position_embeddings: int = 2048,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.q_lora_rank = q_lora_rank
        self.kv_lora_rank = kv_lora_rank
        self.qk_nope_head_dim = qk_nope_head_dim
        self.qk_rope_head_dim = qk_rope_head_dim
        self.v_head_dim = v_head_dim
        self.q_head_dim = qk_nope_head_dim + qk_rope_head_dim
        self.attention_dropout = attention_dropout
        self.softmax_scale = self.q_head_dim ** (-0.5)

        self.q_a_proj = nn.Linear(hidden_size, q_lora_rank, bias=False)
        self.q_a_layernorm = DeepSeekRMSNorm(q_lora_rank)
        self.q_b_proj = nn.Linear(q_lora_rank, num_attention_heads * self.q_head_dim, bias=False)

        self.kv_a_proj_with_mqa = nn.Linear(hidden_size, kv_lora_rank + qk_rope_head_dim, bias=False)
        self.kv_a_layernorm = DeepSeekRMSNorm(kv_lora_rank)
        self.kv_b_proj = nn.Linear(
            kv_lora_rank,
            num_attention_heads * (qk_nope_head_dim + v_head_dim),
            bias=False,
        )

        self.o_proj = nn.Linear(num_attention_heads * v_head_dim, hidden_size, bias=False)

        self.rotary_emb = DeepSeekRotaryEmbedding(
            qk_rope_head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        self._causal_softmax = causal_softmax_mod

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        # Keep everything FP32 for kernel + stable softmax
        if hidden_states.dtype != torch.float32:
            hidden_states = hidden_states.float()

        bsz, q_len, _ = hidden_states.size()

        q = self.q_b_proj(self.q_a_layernorm(self.q_a_proj(hidden_states)))
        q = q.view(bsz, q_len, self.num_heads, self.q_head_dim).transpose(1, 2)
        q_nope, q_pe = torch.split(q, [self.qk_nope_head_dim, self.qk_rope_head_dim], dim=-1)

        compressed_kv = self.kv_a_proj_with_mqa(hidden_states)
        compressed_kv, k_pe = torch.split(compressed_kv, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1)
        k_pe = k_pe.view(bsz, q_len, 1, self.qk_rope_head_dim).transpose(1, 2)

        kv = self.kv_b_proj(self.kv_a_layernorm(compressed_kv))
        kv = kv.view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim).transpose(1, 2)
        k_nope, value_states = torch.split(kv, [self.qk_nope_head_dim, self.v_head_dim], dim=-1)

        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        q_pe, k_pe = apply_rotary_pos_emb(q_pe, k_pe, cos, sin)

        # Assemble full query/key (still using PyTorch ops)
        query_states = torch.empty(bsz, self.num_heads, q_len, self.q_head_dim, device=hidden_states.device, dtype=torch.float32)
        query_states[:, :, :, : self.qk_nope_head_dim] = q_nope
        query_states[:, :, :, self.qk_nope_head_dim :] = q_pe

        key_states = torch.empty(bsz, self.num_heads, q_len, self.q_head_dim, device=hidden_states.device, dtype=torch.float32)
        key_states[:, :, :, : self.qk_nope_head_dim] = k_nope
        key_states[:, :, :, self.qk_nope_head_dim :] = k_pe

        # Attention: matmul + scale (rocBLAS) then fused causal softmax
        attn_scores = torch.matmul(query_states, key_states.transpose(2, 3))
        attn_scores = attn_scores * self.softmax_scale
        attn_scores = attn_scores.contiguous()

        attn_probs = self._causal_softmax.causal_softmax_f32(attn_scores)

        # Dropout (kept for correctness if p>0)
        if self.attention_dropout and self.attention_dropout > 0.0:
            attn_probs = F.dropout(attn_probs, p=self.attention_dropout, training=self.training)

        attn_output = torch.matmul(attn_probs, value_states)
        attn_output = attn_output.transpose(1, 2).contiguous().view(bsz, q_len, self.num_heads * self.v_head_dim)
        attn_output = self.o_proj(attn_output)
        return attn_output

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Force hipcc
os.environ.setdefault("CXX", "hipcc")

# A fused recurrence kernel for diagonal-gated delta attention (diagonal-only KDA).
# Computes for each (b,h):
#   S initialized to 0 (Dv x Dk)
#   for t in [0..T):
#     S_k[i] = sum_j S[i,j]*k[j]
#     err[i] = S_k[i] - v[i]
#     S[i,j] = a[i]*S[i,j] - beta*err[i]*k[j]
#     o[i] = sum_j S[i,j]*q[j]
# Writes o_t (Dv) for every timestep.
#
# Notes:
# - Optimized for fixed-ish dims (Dk,Dv up to 128). Kernel expects Dk==Dv==128 for best perf.
# - One block per (b,h). S stored in shared memory (~64KB).

kda_cpp_source = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

static inline __device__ int64_t idx4(int64_t a, int64_t b, int64_t c, int64_t d,
                                     int64_t B, int64_t C, int64_t D) {
    // layout: [a, b, c, d] with contiguous last dim
    // sizes: A, B, C, D -> flatten = ((a*B + b)*C + c)*D + d
    return ((a * B + b) * C + c) * D + d;
}

__global__ void kda_recurrence_fwd_kernel(
    const float* __restrict__ q,   // [B,T,H,Dk]
    const float* __restrict__ k,   // [B,T,H,Dk]
    const float* __restrict__ v,   // [B,T,H,Dv]
    const float* __restrict__ a,   // [B,T,H,Dv]
    const float* __restrict__ beta,// [B,T,H]
    float* __restrict__ out,       // [B,T,H,Dv]
    int B, int T, int H, int Dk, int Dv)
{
    int b = (int)blockIdx.x;
    int h = (int)blockIdx.y;

    extern __shared__ float smem[];
    float* S   = smem;                 // Dv*Dk
    float* sk  = S + (Dv * Dk);        // Dv
    float* err = sk + Dv;              // Dv
    float* qv  = err + Dv;             // Dk
    float* kv  = qv + Dk;              // Dk
    float* vv  = kv + Dk;              // Dv
    float* av  = vv + Dv;              // Dv

    // init S to 0
    for (int idx = threadIdx.x; idx < Dv * Dk; idx += blockDim.x) {
        S[idx] = 0.0f;
    }
    __syncthreads();

    for (int t = 0; t < T; ++t) {
        // load q,k,v,a into shared
        if (threadIdx.x < Dk) {
            int j = threadIdx.x;
            qv[j] = q[idx4(b, t, h, j, T, H, Dk)];
            kv[j] = k[idx4(b, t, h, j, T, H, Dk)];
        }
        if (threadIdx.x < Dv) {
            int i = threadIdx.x;
            vv[i] = v[idx4(b, t, h, i, T, H, Dv)];
            av[i] = a[idx4(b, t, h, i, T, H, Dv)];
        }
        __syncthreads();

        float bet = 0.0f;
        if (threadIdx.x == 0) {
            bet = beta[((b * T + t) * H + h)];
            // stash in err[0] temporarily for broadcast
            err[0] = bet;
        }
        __syncthreads();
        bet = err[0];

        // compute S_k and error: one thread per i
        if (threadIdx.x < Dv) {
            int i = threadIdx.x;
            float acc = 0.0f;
            const float* Si = S + i * Dk;
            #pragma unroll
            for (int j = 0; j < 128; ++j) {
                if (j < Dk) acc = fmaf(Si[j], kv[j], acc);
            }
            sk[i] = acc;
            err[i] = acc - vv[i];
        }
        __syncthreads();

        // update S: all threads
        for (int idx = threadIdx.x; idx < Dv * Dk; idx += blockDim.x) {
            int i = idx / Dk;
            int j = idx - i * Dk;
            float s = S[idx];
            float ai = av[i];
            float e = err[i];
            float kj = kv[j];
            S[idx] = fmaf(ai, s, -bet * e * kj);
        }
        __syncthreads();

        // compute output o = S @ q: one thread per i
        if (threadIdx.x < Dv) {
            int i = threadIdx.x;
            float acc = 0.0f;
            const float* Si = S + i * Dk;
            #pragma unroll
            for (int j = 0; j < 128; ++j) {
                if (j < Dk) acc = fmaf(Si[j], qv[j], acc);
            }
            out[idx4(b, t, h, i, T, H, Dv)] = acc;
        }
        __syncthreads();
    }
}

torch::Tensor kda_recurrence_fwd(torch::Tensor q,
                                torch::Tensor k,
                                torch::Tensor v,
                                torch::Tensor a,
                                torch::Tensor beta) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP");
    TORCH_CHECK(q.dtype() == torch::kFloat32, "fp32 only");
    TORCH_CHECK(q.is_contiguous(), "q contiguous");
    TORCH_CHECK(k.is_contiguous() && v.is_contiguous() && a.is_contiguous() && beta.is_contiguous(), "inputs contiguous");
    TORCH_CHECK(q.dim()==4 && k.dim()==4 && v.dim()==4 && a.dim()==4, "q,k,v,a must be 4D");
    TORCH_CHECK(beta.dim()==3, "beta must be 3D");

    int B = (int)q.size(0);
    int T = (int)q.size(1);
    int H = (int)q.size(2);
    int Dk = (int)q.size(3);
    int Dv = (int)v.size(3);

    auto out = torch::empty({B, T, H, Dv}, q.options());

    dim3 grid(B, H, 1);
    int threads = 256;
    size_t shmem = sizeof(float) * (Dv * Dk + Dv + Dv + Dk + Dk + Dv + Dv);

    hipLaunchKernelGGL(kda_recurrence_fwd_kernel,
                      grid, dim3(threads), shmem, 0,
                      (const float*)q.data_ptr<float>(),
                      (const float*)k.data_ptr<float>(),
                      (const float*)v.data_ptr<float>(),
                      (const float*)a.data_ptr<float>(),
                      (const float*)beta.data_ptr<float>(),
                      (float*)out.data_ptr<float>(),
                      B, T, H, Dk, Dv);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("kda_recurrence_fwd", &kda_recurrence_fwd, "KDA recurrence forward (HIP)");
}
"""

kda_ext = load_inline(
    name="kda_recurrence_ext",
    cpp_sources=kda_cpp_source,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        head_dim_qk: int,
        head_dim_v: int,
        use_dplr: bool = False,
        dplr_rank: int = 4,
        use_short_conv: bool = True,
        conv_kernel_size: int = 4,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim_qk = head_dim_qk
        self.head_dim_v = head_dim_v
        self.use_dplr = use_dplr
        self.dplr_rank = dplr_rank
        self.use_short_conv = use_short_conv

        self.q_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.a_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=True)
        self.b_proj = nn.Linear(hidden_size, num_heads, bias=True)

        if use_dplr:
            self.l_proj = nn.Linear(hidden_size, num_heads * dplr_rank, bias=False)
            self.r_proj = nn.Linear(hidden_size, num_heads * dplr_rank, bias=False)

        self.o_proj = nn.Linear(num_heads * head_dim_v, hidden_size, bias=False)

        if use_short_conv:
            self.q_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.k_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.v_conv = nn.Conv1d(
                num_heads * head_dim_v, num_heads * head_dim_v,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_v,
                padding=conv_kernel_size - 1
            )

        self.g_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.o_norm = nn.LayerNorm(head_dim_v)
        self.scale = head_dim_qk ** -0.5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape

        q = self.q_proj(x)
        k = self.k_proj(x)
        v = self.v_proj(x)

        if self.use_short_conv:
            q = self.q_conv(q.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            k = self.k_conv(k.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            v = self.v_conv(v.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            q = F.silu(q)
            k = F.silu(k)
            v = F.silu(v)

        q = q.view(batch_size, seq_len, self.num_heads, self.head_dim_qk).contiguous()
        k = k.view(batch_size, seq_len, self.num_heads, self.head_dim_qk).contiguous()
        v = v.view(batch_size, seq_len, self.num_heads, self.head_dim_v).contiguous()

        a = torch.sigmoid(self.a_proj(x)).view(batch_size, seq_len, self.num_heads, self.head_dim_v).contiguous()
        beta = torch.sigmoid(self.b_proj(x)).view(batch_size, seq_len, self.num_heads).contiguous()

        # scale keys
        k = (k * self.scale).contiguous()

        # fused recurrence
        o = kda_ext.kda_recurrence_fwd(q, k, v, a, beta)

        o = self.o_norm(o)
        g = torch.sigmoid(self.g_proj(x)).view(batch_size, seq_len, self.num_heads, self.head_dim_v)
        o = o * g
        o = o.reshape(batch_size, seq_len, self.num_heads * self.head_dim_v)
        o = self.o_proj(o)
        return o


