import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Force HIP toolchain
os.environ.setdefault("CXX", "hipcc")

hip_src = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>

// Simple FlashAttention-style kernel for GQA, FP32 only, causal.
// Computes: out[b,h,q,d] = softmax_j<=q( (q·k)*scale ) @ v
// with implicit KV head sharing: kv_h = h / groups

__device__ __forceinline__ float shfl_down(float v, int delta) {
#if defined(__HIP_PLATFORM_AMD__)
    return __shfl_down(v, delta);
#else
    return __shfl_down(v, delta);
#endif
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    // AMD wavefront is 64, but __shfl_down works up to 64 lanes.
    for (int offset = 32; offset > 0; offset >>= 1) {
        v += shfl_down(v, offset);
    }
    return v;
}

__device__ __forceinline__ float warp_reduce_max(float v) {
    for (int offset = 32; offset > 0; offset >>= 1) {
        float other = shfl_down(v, offset);
        v = v > other ? v : other;
    }
    return v;
}

// Reduce across 128 threads as 2 wavefronts of 64.
__device__ __forceinline__ float block_reduce_sum_128(float v, float* shared) {
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int warp = tid >> 6; // 0 or 1
    v = warp_reduce_sum(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();
    float out = 0.0f;
    if (warp == 0) {
        out = (lane < 2) ? shared[lane] : 0.0f;
        out = warp_reduce_sum(out);
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ float block_reduce_max_128(float v, float* shared) {
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int warp = tid >> 6;
    v = warp_reduce_max(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();
    float out = -INFINITY;
    if (warp == 0) {
        out = (lane < 2) ? shared[lane] : -INFINITY;
        out = warp_reduce_max(out);
    }
    __syncthreads();
    return shared[0];
}

__global__ void gqa_attn_fwd_fp32(
    const float* __restrict__ Q, // [B,H,S,D]
    const float* __restrict__ K, // [B,HKV,S,D]
    const float* __restrict__ V, // [B,HKV,S,D]
    float* __restrict__ O,       // [B,H,S,D]
    int B, int H, int HKV, int S, int D,
    int groups,
    float scale
) {
    // block: (b,h,q)
    int qpos = (int)blockIdx.x;
    int h = (int)blockIdx.y;
    int b = (int)blockIdx.z;

    int tid = (int)threadIdx.x; // 0..127
    if (tid >= D) return; // expect D<=128

    int kv_h = h / groups;

    // pointers
    // layout contiguous: (((b*H + h)*S + qpos)*D + d)
    const float* q_ptr = Q + (((b * H + h) * S + qpos) * D);
    const float* k_base = K + (((b * HKV + kv_h) * S) * D);
    const float* v_base = V + (((b * HKV + kv_h) * S) * D);

    float qd = q_ptr[tid];

    __shared__ float red[2];
    __shared__ float sh_expw;
    __shared__ float sh_sumw;

    // Pass 1: find max logit
    float m = -INFINITY;
    for (int j = 0; j <= qpos; ++j) {
        const float* k_ptr = k_base + j * D;
        float prod = qd * k_ptr[tid];
        float dot = block_reduce_sum_128(prod, red);
        float logit = dot * scale;
        // broadcast dot via shared[0]
        m = logit > m ? logit : m;
        __syncthreads();
    }
    // Reduce max across iterations is per-thread identical; m already scalar per thread but computed from broadcasted logit.
    // Still safe.

    // Pass 2: compute sumw and weighted sum of V
    float out_d = 0.0f;
    float sumw = 0.0f;
    for (int j = 0; j <= qpos; ++j) {
        const float* k_ptr = k_base + j * D;
        float prod = qd * k_ptr[tid];
        float dot = block_reduce_sum_128(prod, red);
        float logit = dot * scale;
        float expw;
        if (tid == 0) {
            expw = __expf(logit - m);
            sh_expw = expw;
        }
        __syncthreads();
        expw = sh_expw;
        const float* v_ptr = v_base + j * D;
        out_d += expw * v_ptr[tid];
        if (tid == 0) sumw += expw;
        __syncthreads();
    }
    if (tid == 0) sh_sumw = sumw;
    __syncthreads();
    float inv = 1.0f / sh_sumw;
    O[(((b * H + h) * S + qpos) * D) + tid] = out_d * inv;
}

torch::Tensor gqa_attn_fwd(torch::Tensor q, torch::Tensor k, torch::Tensor v, int64_t groups, double scale) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP");
    TORCH_CHECK(k.is_cuda(), "k must be CUDA/HIP");
    TORCH_CHECK(v.is_cuda(), "v must be CUDA/HIP");
    TORCH_CHECK(q.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(k.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(v.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(q.is_contiguous(), "q must be contiguous");
    TORCH_CHECK(k.is_contiguous(), "k must be contiguous");
    TORCH_CHECK(v.is_contiguous(), "v must be contiguous");

    int B = (int)q.size(0);
    int H = (int)q.size(1);
    int S = (int)q.size(2);
    int D = (int)q.size(3);
    int HKV = (int)k.size(1);

    auto out = torch::empty({B, H, S, D}, q.options());

    dim3 grid(S, H, B);
    dim3 block(128);

    hipStream_t stream = at::hip::getDefaultHIPStream();
    hipLaunchKernelGGL(gqa_attn_fwd_fp32, grid, block, 0, stream,
        (const float*)q.data_ptr<float>(),
        (const float*)k.data_ptr<float>(),
        (const float*)v.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        B, H, HKV, S, D,
        (int)groups,
        (float)scale
    );
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gqa_attn_fwd", &gqa_attn_fwd, "GQA attention forward (FP32, causal)");
}
'''

ext = load_inline(
    name="gqa_attn_ext",
    cpp_sources="",
    cuda_sources=hip_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


def rotate_half(x):
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin):
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        # FP32 path
        if hidden_states.dtype != torch.float32:
            hidden_states = hidden_states.float()

        bsz, q_len, _ = hidden_states.size()

        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2).contiguous()
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2).contiguous()
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2).contiguous()

        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        query_states = query_states.contiguous()
        key_states = key_states.contiguous()
        value_states = value_states.contiguous()

        # Custom fused attention (no repeat_kv, no materialized attn_weights)
        attn_out = ext.gqa_attn_fwd(query_states, key_states, value_states, self.num_key_value_groups, float(self.softmax_scale))

        attn_out = attn_out.transpose(1, 2).contiguous().view(bsz, q_len, self.num_heads * self.head_dim)
        return self.o_proj(attn_out)


