_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <hip/hip_runtime.h>

#include <c10/util/BFloat16.h>
#include <c10/util/Half.h>
#include <c10/util/Float8_e4m3fn.h>
#include <c10/util/Float8_e5m2.h>

namespace {

template <typename in_t>
__device__ __forceinline__ float to_f32(in_t v);

template <>
__device__ __forceinline__ float to_f32<c10::Half>(c10::Half v) {
    return (float)(at::Half)v;
}

template <>
__device__ __forceinline__ float to_f32<c10::BFloat16>(c10::BFloat16 v) {
    return (float)v;
}

template <typename fp8_t, typename in_t>
__global__ void quantize_fp8_kernel(const in_t* __restrict__ x,
                                   fp8_t* __restrict__ out,
                                   int64_t n,
                                   float scale,
                                   float fp8_max) {
    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        float v = to_f32<in_t>(x[i]) * scale;
        // clamp
        v = fminf(fp8_max, fmaxf(-fp8_max, v));
        out[i] = fp8_t(v);
    }
}

} // namespace

// quantize x (half/bf16) -> fp8 tensor, given scalar scale and fp8_max.
torch::Tensor quantize_to_fp8(torch::Tensor x, double scale, double fp8_max, bool use_e4m3) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16,
                "x must be fp16 or bf16");
    auto n = x.numel();

    at::ScalarType out_ty = use_e4m3 ? at::kFloat8E4M3FN : at::kFloat8E5M2;
    auto out = torch::empty_like(x, x.options().dtype(out_ty));

    const int threads = 256;
    const int blocks = (int)((n + threads - 1) / threads);
    auto stream = at::cuda::getDefaultCUDAStream();

    float s = (float)scale;
    float m = (float)fp8_max;

    if (use_e4m3) {
        if (x.scalar_type() == at::kHalf) {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e4m3fn, c10::Half>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::Half*)x.data_ptr<c10::Half>(),
                               (c10::Float8_e4m3fn*)out.data_ptr(),
                               (int64_t)n, s, m);
        } else {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e4m3fn, c10::BFloat16>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::BFloat16*)x.data_ptr<c10::BFloat16>(),
                               (c10::Float8_e4m3fn*)out.data_ptr(),
                               (int64_t)n, s, m);
        }
    } else {
        if (x.scalar_type() == at::kHalf) {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e5m2, c10::Half>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::Half*)x.data_ptr<c10::Half>(),
                               (c10::Float8_e5m2*)out.data_ptr(),
                               (int64_t)n, s, m);
        } else {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e5m2, c10::BFloat16>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::BFloat16*)x.data_ptr<c10::BFloat16>(),
                               (c10::Float8_e5m2*)out.data_ptr(),
                               (int64_t)n, s, m);
        }
    }

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("quantize_to_fp8", &quantize_to_fp8, "Quantize (fp16/bf16) -> fp8 (HIP)");
}
'''

_quant_mod = load_inline(
    name="quant_fp8_ext",
    cpp_sources=_src,
    functions=None,
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

        # Cached FP8 weight + inverse scale (valid for inference / fixed weights)
        self.register_buffer("_w_fp8", None, persistent=False)
        self.register_buffer("_w_scale_inv", None, persistent=False)
        self._w_version = -1

    @staticmethod
    def _compute_scale(x: torch.Tensor, fp8_max: float) -> torch.Tensor:
        amax = x.abs().max()
        return fp8_max / amax.clamp(min=1e-12)

    def _maybe_update_weight_cache(self):
        # Refresh cache if weight changed (tracked via _version)
        v = self.weight._version
        if self._w_fp8 is not None and self._w_version == v:
            return

        w_t = self.weight.t().contiguous()  # (N, K)
        w_scale = self._compute_scale(w_t, self.fp8_max)
        self._w_scale_inv = (1.0 / w_scale).to(torch.float32)
        self._w_fp8 = _quant_mod.quantize_to_fp8(w_t, float(w_scale.item()), float(self.fp8_max), bool(self.use_e4m3))
        self._w_version = v

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_dtype = x.dtype
        b, s, _ = x.shape
        x_2d = x.view(-1, self.K)

        # Activation scale (dynamic)
        x_scale = self._compute_scale(x_2d, self.fp8_max)
        x_scale_inv = (1.0 / x_scale).to(torch.float32)

        # Quantize activations with custom HIP kernel
        x_fp8 = _quant_mod.quantize_to_fp8(x_2d, float(x_scale.item()), float(self.fp8_max), bool(self.use_e4m3))

        # Cached pre-quantized weights
        self._maybe_update_weight_cache()

        out = torch._scaled_mm(
            x_fp8,
            self._w_fp8.t(),
            scale_a=x_scale_inv,
            scale_b=self._w_scale_inv,
            out_dtype=input_dtype,
        )
        return out.view(b, s, self.N)


