import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force HIP compilation on ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused INT4 unpack + dequant + GEMM
# x: (M,K) fp16
# weight_packed: (N,K/2) uint8 packed int4 (low nibble first)
# scales: (N, K/group_size) fp16
# out: (M,N) fp16, accumulate fp32

src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

__device__ __forceinline__ int int4_from_packed(uint8_t byte, bool high) {
    return high ? ((byte >> 4) & 0x0F) : (byte & 0x0F);
}

__global__ void int4_gemm_fused_kernel(
    const half* __restrict__ x,        // (M,K)
    const uint8_t* __restrict__ wpk,   // (N,K/2)
    const half* __restrict__ scales,   // (N,Kg)
    half* __restrict__ out,            // (M,N)
    int M, int N, int K, int Kg, int group_size)
{
    int m = (int)(blockIdx.y * blockDim.y + threadIdx.y);
    int n = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    if (m >= M || n >= N) return;

    float acc = 0.0f;

    const half* xrow = x + (size_t)m * K;
    const uint8_t* wrow = wpk + (size_t)n * (K/2);
    const half* srow = scales + (size_t)n * Kg;

    for (int k2 = 0; k2 < K/2; ++k2) {
        uint8_t byte = wrow[k2];

        int k0 = k2 * 2;
        int g0 = k0 / group_size;
        float s0 = __half2float(srow[g0]);
        int wq0 = int4_from_packed(byte, false);
        float w0 = s0 * ((float)wq0 - 8.0f);
        float x0 = __half2float(xrow[k0]);
        acc = fmaf(x0, w0, acc);

        int k1 = k0 + 1;
        int g1 = k1 / group_size;
        float s1 = __half2float(srow[g1]);
        int wq1 = int4_from_packed(byte, true);
        float w1 = s1 * ((float)wq1 - 8.0f);
        float x1 = __half2float(xrow[k1]);
        acc = fmaf(x1, w1, acc);
    }

    out[(size_t)m * N + n] = __float2half_rn(acc);
}

torch::Tensor int4_gemm_fused_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int64_t group_size) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(weight_packed.is_cuda(), "weight_packed must be CUDA/HIP tensor");
    TORCH_CHECK(scales.is_cuda(), "scales must be CUDA/HIP tensor");

    TORCH_CHECK(x.scalar_type() == at::kHalf, "x must be fp16");
    TORCH_CHECK(weight_packed.scalar_type() == at::kByte, "weight_packed must be uint8");
    TORCH_CHECK(scales.scalar_type() == at::kHalf, "scales must be fp16");

    TORCH_CHECK(x.dim() == 2, "x must be 2D (M,K)");
    TORCH_CHECK(weight_packed.dim() == 2, "weight_packed must be 2D (N,K/2)");
    TORCH_CHECK(scales.dim() == 2, "scales must be 2D (N,Kg)");

    int64_t M = x.size(0);
    int64_t K = x.size(1);
    int64_t N = weight_packed.size(0);
    TORCH_CHECK(weight_packed.size(1) * 2 == K, "weight_packed second dim must be K/2");
    TORCH_CHECK(K % group_size == 0, "K must be divisible by group_size");
    TORCH_CHECK(K % 2 == 0, "K must be even");

    int64_t Kg = K / group_size;
    TORCH_CHECK(scales.size(0) == N && scales.size(1) == Kg, "scales must be (N, K/group_size)");

    auto out = torch::empty({M, N}, torch::TensorOptions().dtype(at::kHalf).device(x.device()));

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    hipLaunchKernelGGL(int4_gemm_fused_kernel,
        grid, block, 0, 0,
        (const half*)x.data_ptr<at::Half>(),
        (const uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (const half*)scales.data_ptr<at::Half>(),
        (half*)out.data_ptr<at::Half>(),
        (int)M, (int)N, (int)K, (int)Kg, (int)group_size);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("int4_gemm_fused_hip", &int4_gemm_fused_hip, "Fused INT4 GEMM (HIP)");
}
"""

int4ext = load_inline(
    name="int4_gemm_fused_ext",
    cpp_sources="",
    cuda_sources=src,
    functions=None,
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        assert K % group_size == 0
        assert K % 2 == 0

        # Match reference init exactly: create buffers on CPU; KernelBench will move model to GPU.
        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )
        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape
        x2d = x.view(-1, self.K).contiguous()
        out2d = int4ext.int4_gemm_fused_hip(x2d, self.weight_packed, self.scales, self.group_size)
        return out2d.view(batch_size, seq_len, self.N)


