import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ.setdefault("CXX", "hipcc")

hip_src = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>

__device__ __forceinline__ float shfl_down(float v, int delta) {
    return __shfl_down(v, delta);
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    // Reduce within 64-lane wavefront
    for (int offset = 32; offset > 0; offset >>= 1) v += shfl_down(v, offset);
    return v;
}

__device__ __forceinline__ float warp_reduce_max(float v) {
    for (int offset = 32; offset > 0; offset >>= 1) {
        float o = shfl_down(v, offset);
        v = v > o ? v : o;
    }
    return v;
}

__device__ __forceinline__ float block_reduce_sum_128(float v, float* shared) {
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int warp = tid >> 6; // 0 or 1

    v = warp_reduce_sum(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();

    if (warp == 0) {
        float x = (lane < 2) ? shared[lane] : 0.0f;
        x = warp_reduce_sum(x);
        if (lane == 0) shared[0] = x;
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ float block_reduce_max_128(float v, float* shared) {
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int warp = tid >> 6;

    v = warp_reduce_max(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();

    if (warp == 0) {
        float x = (lane < 2) ? shared[lane] : -INFINITY;
        x = warp_reduce_max(x);
        if (lane == 0) shared[0] = x;
    }
    __syncthreads();
    return shared[0];
}

__global__ void gqa_attn_fwd_fp32(
    const float* __restrict__ Q, // [B,H,S,D]
    const float* __restrict__ K, // [B,HKV,S,D]
    const float* __restrict__ V, // [B,HKV,S,D]
    float* __restrict__ O,       // [B,H,S,D]
    int B, int H, int HKV, int S, int D,
    int groups,
    float scale
) {
    int qpos = (int)blockIdx.x;
    int h = (int)blockIdx.y;
    int b = (int)blockIdx.z;

    int tid = (int)threadIdx.x; // 0..127
    if (tid >= D) return;

    int kv_h = h / groups;

    const float* q_ptr = Q + (((b * H + h) * S + qpos) * D);
    const float* k_base = K + (((b * HKV + kv_h) * S) * D);
    const float* v_base = V + (((b * HKV + kv_h) * S) * D);

    float qd = q_ptr[tid];

    __shared__ float red[2];
    __shared__ float sh_expw;
    __shared__ float sh_sumw;

    // Pass 1: max
    float m = -INFINITY;
    for (int j = 0; j <= qpos; ++j) {
        const float* k_ptr = k_base + j * D;
        float dot = block_reduce_sum_128(qd * k_ptr[tid], red);
        float logit = dot * scale;
        m = logit > m ? logit : m;
    }

    // Pass 2: sum and output
    float out_d = 0.0f;
    float sumw = 0.0f;
    for (int j = 0; j <= qpos; ++j) {
        const float* k_ptr = k_base + j * D;
        float dot = block_reduce_sum_128(qd * k_ptr[tid], red);
        float logit = dot * scale;
        if (tid == 0) {
            float expw = __expf(logit - m);
            sh_expw = expw;
            sumw += expw;
        }
        __syncthreads();
        float expw = sh_expw;
        const float* v_ptr = v_base + j * D;
        out_d += expw * v_ptr[tid];
        __syncthreads();
    }
    if (tid == 0) sh_sumw = sumw;
    __syncthreads();
    float inv = 1.0f / sh_sumw;
    O[(((b * H + h) * S + qpos) * D) + tid] = out_d * inv;
}

torch::Tensor gqa_attn_fwd(torch::Tensor q, torch::Tensor k, torch::Tensor v, int64_t groups, double scale) {
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "tensors must be on GPU");
    TORCH_CHECK(q.scalar_type() == at::kFloat && k.scalar_type() == at::kFloat && v.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(), "contiguous required");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "expected [B,H,S,D]");

    int B = (int)q.size(0);
    int H = (int)q.size(1);
    int S = (int)q.size(2);
    int D = (int)q.size(3);
    int HKV = (int)k.size(1);

    TORCH_CHECK(D <= 128, "D must be <= 128 for this kernel");

    auto out = torch::empty({B, H, S, D}, q.options());

    dim3 grid(S, H, B);
    dim3 block(128);
    hipStream_t stream = at::hip::getDefaultHIPStream();

    hipLaunchKernelGGL(gqa_attn_fwd_fp32, grid, block, 0, stream,
        (const float*)q.data_ptr<float>(),
        (const float*)k.data_ptr<float>(),
        (const float*)v.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        B, H, HKV, S, D,
        (int)groups,
        (float)scale
    );
    return out;
}

