__device__ __forceinline__ float to_f32<c10::Half>(c10::Half v) {
    return (float)v;
}

template <>
__device__ __forceinline__ float to_f32<c10::BFloat16>(c10::BFloat16 v) {
    return (float)v;
}

template <typename fp8_t, typename in_t>
__global__ void quantize_fp8_kernel(const in_t* __restrict__ x,
                                   fp8_t* __restrict__ out,
                                   int64_t n,
                                   float scale,
                                   float fp8_max) {
    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        float v = to_f32<in_t>(x[i]) * scale;
        v = fminf(fp8_max, fmaxf(-fp8_max, v));
        out[i] = fp8_t(v);
    }
}

