    m.def("silu_mul_hip", &silu_mul_hip, "silu(a)*b (HIP, FP32)");
    m.def("moe_weighted_sum_hip", &moe_weighted_sum_hip, "MoE weighted sum over top-k (HIP, FP32)");
}
