import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ.setdefault("CXX", "hipcc")

kda_cpp_source = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

static inline __device__ int64_t idx4(int64_t a, int64_t b, int64_t c, int64_t d,
                                     int64_t B, int64_t C, int64_t D) {
    return ((a * B + b) * C + c) * D + d;
}

// S: [B,H,Dv,Dk] global state buffer (initialized to 0)
__global__ void kda_recurrence_fwd_kernel_gmem(
    const float* __restrict__ q,    // [B,T,H,Dk]
    const float* __restrict__ k,    // [B,T,H,Dk]
    const float* __restrict__ v,    // [B,T,H,Dv]
    const float* __restrict__ a,    // [B,T,H,Dv]
    const float* __restrict__ beta, // [B,T,H]
    float* __restrict__ S,          // [B,H,Dv,Dk]
    float* __restrict__ out,        // [B,T,H,Dv]
    int B, int T, int H, int Dk, int Dv)
{
    int b = (int)blockIdx.x;
    int h = (int)blockIdx.y;

    extern __shared__ float smem[];
    float* qv = smem;        // Dk
    float* kv = qv + Dk;     // Dk

    // pointer to this (b,h) state
    float* Sbh = S + (((b * H + h) * Dv) * Dk);

    for (int t = 0; t < T; ++t) {
        // load q,k into shared
        if (threadIdx.x < Dk) {
            int j = threadIdx.x;
            qv[j] = q[idx4(b, t, h, j, T, H, Dk)];
            kv[j] = k[idx4(b, t, h, j, T, H, Dk)];
        }
        __syncthreads();

        float bet = 0.0f;
        if (threadIdx.x == 0) {
            bet = beta[((b * T + t) * H + h)];
            kv[0] = kv[0]; // keep compiler from reordering too much
        }
        __syncthreads();
        if (threadIdx.x == 0) {
            // broadcast via qv[0]
            qv[0] = bet;
        }
        __syncthreads();
        bet = qv[0];

        // compute err_i and o_i by one thread per i
        // store err_i temporarily in out (reuse out as scratch not allowed). So we recompute err in update threads via two-pass.
        // Pass1: compute err_i and store to a small global scratch in-place in out for this timestep? can't.
        // Instead: compute err_i in registers for i-threads and write to a small per-(b,h) scratch buffer provided by caller.
        // We avoid extra output by using a separate scratch tensor.

        // Scratch is passed via S tail? Not safe. We require caller to pass scratch [B,H,Dv].
    }
}

__global__ void kda_recurrence_fwd_kernel(
    const float* __restrict__ q,    // [B,T,H,Dk]
    const float* __restrict__ k,    // [B,T,H,Dk]
    const float* __restrict__ v,    // [B,T,H,Dv]
    const float* __restrict__ a,    // [B,T,H,Dv]
    const float* __restrict__ beta, // [B,T,H]
    float* __restrict__ S,          // [B,H,Dv,Dk]
    float* __restrict__ scratch,    // [B,H,Dv]
    float* __restrict__ out,        // [B,T,H,Dv]
    int B, int T, int H, int Dk, int Dv)
{
    int b = (int)blockIdx.x;
    int h = (int)blockIdx.y;

    extern __shared__ float smem[];
    float* qv = smem;        // Dk
    float* kv = qv + Dk;     // Dk

    float* Sbh = S + (((b * H + h) * Dv) * Dk);
    float* scr = scratch + ((b * H + h) * Dv);

    for (int t = 0; t < T; ++t) {
        if (threadIdx.x < Dk) {
            int j = threadIdx.x;
            qv[j] = q[idx4(b, t, h, j, T, H, Dk)];
            kv[j] = k[idx4(b, t, h, j, T, H, Dk)];
        }
        __syncthreads();

        float bet = 0.0f;
        if (threadIdx.x == 0) bet = beta[((b * T + t) * H + h)];
        // broadcast via qv[0]
        __syncthreads();
        if (threadIdx.x == 0) qv[0] = bet;
        __syncthreads();
        bet = qv[0];

        // Pass 1: compute err[i] = (S @ k)[i] - v[i], store to scratch
        if (threadIdx.x < Dv) {
            int i = threadIdx.x;
            const float* Si = Sbh + i * Dk;
            float acc = 0.0f;
            #pragma unroll
            for (int j = 0; j < 128; ++j) {
                if (j < Dk) acc = fmaf(Si[j], kv[j], acc);
            }
            float vv = v[idx4(b, t, h, i, T, H, Dv)];
            scr[i] = acc - vv;
        }
        __syncthreads();

        // Pass 2: update S[i,j] = a[i]*S[i,j] - beta*err[i]*k[j]
        for (int idx = threadIdx.x; idx < Dv * Dk; idx += blockDim.x) {
            int i = idx / Dk;
            int j = idx - i * Dk;
            float ai = a[idx4(b, t, h, i, T, H, Dv)];
            float e = scr[i];
            float kj = kv[j];
            float s = Sbh[idx];
            Sbh[idx] = fmaf(ai, s, -bet * e * kj);
        }
        __syncthreads();

        // Pass 3: compute o[i] = (S @ q)[i] and write out
        if (threadIdx.x < Dv) {
            int i = threadIdx.x;
            const float* Si = Sbh + i * Dk;
            float acc = 0.0f;
            #pragma unroll
            for (int j = 0; j < 128; ++j) {
                if (j < Dk) acc = fmaf(Si[j], qv[j], acc);
            }
            out[idx4(b, t, h, i, T, H, Dv)] = acc;
        }
        __syncthreads();
    }
}

torch::Tensor kda_recurrence_fwd(torch::Tensor q,
                                torch::Tensor k,
                                torch::Tensor v,
                                torch::Tensor a,
                                torch::Tensor beta) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP");
    TORCH_CHECK(q.dtype() == torch::kFloat32, "fp32 only");
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous() && a.is_contiguous() && beta.is_contiguous(), "contiguous inputs");
    TORCH_CHECK(q.dim()==4 && k.dim()==4 && v.dim()==4 && a.dim()==4, "q,k,v,a must be 4D");
    TORCH_CHECK(beta.dim()==3, "beta must be 3D");

    int B = (int)q.size(0);
    int T = (int)q.size(1);
    int H = (int)q.size(2);
    int Dk = (int)q.size(3);
    int Dv = (int)v.size(3);

    auto out = torch::empty({B, T, H, Dv}, q.options());
    auto S = torch::zeros({B, H, Dv, Dk}, q.options());
    auto scratch = torch::empty({B, H, Dv}, q.options());

    dim3 grid(B, H, 1);
    int threads = 256;
    size_t shmem = sizeof(float) * (Dk + Dk);

    hipLaunchKernelGGL(kda_recurrence_fwd_kernel,
                      grid, dim3(threads), shmem, 0,
                      (const float*)q.data_ptr<float>(),
                      (const float*)k.data_ptr<float>(),
                      (const float*)v.data_ptr<float>(),
                      (const float*)a.data_ptr<float>(),
                      (const float*)beta.data_ptr<float>(),
                      (float*)S.data_ptr<float>(),
                      (float*)scratch.data_ptr<float>(),
                      (float*)out.data_ptr<float>(),
                      B, T, H, Dk, Dv);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("kda_recurrence_fwd", &kda_recurrence_fwd, "KDA recurrence forward (HIP)");
}
"""

