#include <c10/util/BFloat16.h>
#include <c10/util/Half.h>
#include <c10/util/Float8_e4m3fn.h>
#include <c10/util/Float8_e5m2.h>

namespace {

template <typename in_t>
__device__ __forceinline__ float to_f32(in_t v);

template <>
__device__ __forceinline__ float to_f32<c10::Half>(c10::Half v) { return (float)v; }

template <>
__device__ __forceinline__ float to_f32<c10::BFloat16>(c10::BFloat16 v) { return (float)v; }

template <>
__device__ __forceinline__ float to_f32<c10::Float8_e4m3fn>(c10::Float8_e4m3fn v) { return (float)v; }

template <>
__device__ __forceinline__ float to_f32<c10::Float8_e5m2>(c10::Float8_e5m2 v) { return (float)v; }


template <typename fp8_t, typename in_t>
__global__ void quantize_fp8_kernel(const in_t* __restrict__ x,
                                   fp8_t* __restrict__ out,
                                   int64_t n,
                                   float scale,
                                   float fp8_max) {
    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        float v = to_f32<in_t>(x[i]) * scale;
        v = fminf(fp8_max, fmaxf(-fp8_max, v));
        out[i] = fp8_t(v);
    }
}


template <typename fp8_t>
__global__ void dequantize_fp8_to_half_kernel(const fp8_t* __restrict__ x,
                                             c10::Half* __restrict__ out,
                                             int64_t n,
                                             float scale_inv) {
    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        float v = to_f32<fp8_t>(x[i]) * scale_inv;
        out[i] = (c10::Half)v;
    }
}

} // namespace


torch::Tensor quantize_to_fp8(torch::Tensor x, double scale, double fp8_max, bool use_e4m3) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16,
                "x must be fp16 or bf16");

    int64_t n = x.numel();
    at::ScalarType out_ty = use_e4m3 ? at::kFloat8_e4m3fn : at::kFloat8_e5m2;
    auto out = torch::empty(x.sizes(), x.options().dtype(out_ty));

    const int threads = 256;
    const int blocks = (int)((n + threads - 1) / threads);
    auto stream = at::cuda::getDefaultCUDAStream();

    float s = (float)scale;
    float m = (float)fp8_max;

    if (use_e4m3) {
        if (x.scalar_type() == at::kHalf) {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e4m3fn, c10::Half>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::Half*)x.data_ptr<c10::Half>(),
                               (c10::Float8_e4m3fn*)out.data_ptr<c10::Float8_e4m3fn>(),
                               n, s, m);
        } else {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e4m3fn, c10::BFloat16>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::BFloat16*)x.data_ptr<c10::BFloat16>(),
                               (c10::Float8_e4m3fn*)out.data_ptr<c10::Float8_e4m3fn>(),
                               n, s, m);
        }
    } else {
        if (x.scalar_type() == at::kHalf) {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e5m2, c10::Half>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::Half*)x.data_ptr<c10::Half>(),
                               (c10::Float8_e5m2*)out.data_ptr<c10::Float8_e5m2>(),
                               n, s, m);
        } else {
            hipLaunchKernelGGL((quantize_fp8_kernel<c10::Float8_e5m2, c10::BFloat16>),
                               dim3(blocks), dim3(threads), 0, stream,
                               (const c10::BFloat16*)x.data_ptr<c10::BFloat16>(),
                               (c10::Float8_e5m2*)out.data_ptr<c10::Float8_e5m2>(),
                               n, s, m);
        }
    }

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}


torch::Tensor dequantize_fp8_to_half(torch::Tensor x_fp8, double scale_inv, bool use_e4m3) {
    TORCH_CHECK(x_fp8.is_cuda(), "x_fp8 must be CUDA/HIP tensor");
    TORCH_CHECK(x_fp8.scalar_type() == (use_e4m3 ? at::kFloat8_e4m3fn : at::kFloat8_e5m2),
                "x_fp8 dtype mismatch");

    int64_t n = x_fp8.numel();
    auto out = torch::empty(x_fp8.sizes(), x_fp8.options().dtype(at::kHalf));

    const int threads = 256;
    const int blocks = (int)((n + threads - 1) / threads);
    auto stream = at::cuda::getDefaultCUDAStream();

    float s = (float)scale_inv;

    if (use_e4m3) {
        hipLaunchKernelGGL((dequantize_fp8_to_half_kernel<c10::Float8_e4m3fn>),
                           dim3(blocks), dim3(threads), 0, stream,
                           (const c10::Float8_e4m3fn*)x_fp8.data_ptr<c10::Float8_e4m3fn>(),
                           (c10::Half*)out.data_ptr<c10::Half>(),
                           n, s);
    } else {
        hipLaunchKernelGGL((dequantize_fp8_to_half_kernel<c10::Float8_e5m2>),
                           dim3(blocks), dim3(threads), 0, stream,
                           (const c10::Float8_e5m2*)x_fp8.data_ptr<c10::Float8_e5m2>(),
                           (c10::Half*)out.data_ptr<c10::Half>(),
                           n, s);
    }

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}


PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("quantize_to_fp8", &quantize_to_fp8, "Quantize (fp16/bf16) -> fp8 (HIP)");
    m.def("dequantize_fp8_to_half", &dequantize_fp8_to_half, "Dequantize fp8 -> fp16 (HIP)");
}
